begin;
select plan(9);
insert into auth.users(id,email) values ('f1000000-0000-0000-0000-000000000001','admin-management@example.test'),('f1000000-0000-0000-0000-000000000002','worker-management@example.test'),('f1000000-0000-0000-0000-000000000003','new-management@example.test');
insert into public.profiles(id,display_name,role,active) values ('f1000000-0000-0000-0000-000000000001','Admin','admin',true),('f1000000-0000-0000-0000-000000000002','Worker','collaborator',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.register_collaborator('f1000000-0000-0000-0000-000000000003','New')$$,'admin registers collaborator');
select is((select role::text from public.profiles where id='f1000000-0000-0000-0000-000000000003'),'collaborator','new user is never admin');
select lives_ok($$select public.update_collaborator('f1000000-0000-0000-0000-000000000003','Updated',false)$$,'admin deactivates collaborator');
select is((select active from public.profiles where id='f1000000-0000-0000-0000-000000000003'),false,'inactive state persists');
select throws_ok($$select public.update_collaborator('f1000000-0000-0000-0000-000000000001','Admin',false)$$,'P0001','collaborator not found','cannot modify admin through collaborator endpoint');
select throws_ok($$update public.profiles set role='admin'$$,'42501',null,'direct role modification denied');
select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.update_collaborator('f1000000-0000-0000-0000-000000000003','Tampered',true)$$,'42501','access denied','worker cannot update');
select throws_ok($$select public.register_collaborator('f1000000-0000-0000-0000-000000000003','Tampered')$$,'42501','access denied','worker cannot register');
select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.profiles),0::bigint,'inactive collaborator cannot read profiles');
select * from finish();
rollback;
